// text-scramble. Generated by scripts/build-esm.mjs from the DEFAULTS of the engine.

export interface TextScrambleSettings {
  /** Colour of the scrambled glyphs, or auto. Default: 'auto'. */
  color?: string;
  /** sets or characters. Glyphs shuffled through. Default: 'symbols digits'. */
  chars?: string;
  /** s. Time one character stays scrambled. Default: 0.5. */
  duration?: number;
  /** s. Delay between two characters. Default: 0.03. */
  stagger?: number;
  /** s. Longest wave, first to last character. Default: 1.2. */
  spread?: number;
  /** per s. How often a scrambled glyph changes. Default: 30. */
  speed?: number;
  /** order. Which characters settle first. Default: 'start'. */
  order?: string;
  /** s. Wait before the effect starts. Default: 0. */
  delay?: number;
  /** share of the viewport. Where scroll starts it. Default: 0.86. */
  trigger?: number;
  /** true or false. Scroll plays on every entry. Default: false. */
  replay?: boolean;
}

export interface Instance {
  destroy(): void;
  [key: string]: unknown;
}

export interface Library {
  mount(element: Element, settings?: TextScrambleSettings): Instance | null;
  destroy(element: Element): void;
  auto(root?: ParentNode): void;
  defaults: Required<TextScrambleSettings> | null;
  [key: string]: unknown;
}

/** Runs the engine once and returns window.TextScramble, or null on a server. */
export function load(): Library | null;
/** Mounts the effect on one element. Does nothing, and returns null, on a server. */
export function mount(element: Element | null, settings?: TextScrambleSettings): Instance | null;
export function destroy(element: Element | null): void;
/** Mounts every marked element inside root, the document by default. */
export function auto(root?: ParentNode): void;
export function play(element: Element | null): void;
